                                    healthSleep: String(item.health?.sleep ?? 7),
                                    healthEating: String(item.health?.healthyEating ?? 5),
                                    financeExpense: String(item.finance?.expense ?? 0),
                                    financeIncome: String(item.finance?.income ?? 0),
