"use client";

import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type FormEvent,
} from "react";
import { useSearchParams, useRouter } from "next/navigation";
import Link from "next/link";
import {
  collection,
  getDocs,
  onSnapshot,
  orderBy,
  query,
  where,
  type Timestamp,
} from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useNsgramAuth } from "@/components/nsgram/NsgramAuthProvider";
import { useVoiceCall } from "@/components/nsgram/useVoiceCall";
import { IncomingCallModal, ActiveCallOverlay, CallErrorBanner } from "@/components/nsgram/VoiceCallUI";
import { API_BASE } from "@/lib/api";

// ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

type Message = {
  id: string;
  senderId: string;
  text: string;
  createdAt?: Timestamp | string | null;
  read?: boolean;
  replyTo?: { id: string; text: string; senderId: string; senderName: string };
  reactions?: Record<string, string>; // userId -> emoji
  audioUrl?: string;
  // Call log fields
  type?: "call";
  callType?: "voice" | "video";
  callStatus?: "completed" | "missed" | "declined";
  callDuration?: number; // seconds
};

type Conversation = {
  id: string;
  participants: string[];
  lastMessage?: string;
  lastMessageAt?: Timestamp | string | null;
  lastMessageBy?: string;
  lastMessageRead?: boolean;
  createdAt?: Timestamp | string | null;
};

// ΓöÇΓöÇΓöÇ Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function toDate(value: Timestamp | string | null | undefined): Date | null {
  if (!value) return null;
  if (typeof value === "string") return new Date(value);
  if ("toDate" in value) return value.toDate();
  return null;
}

function formatRelative(value: Timestamp | string | null | undefined): string {
  const date = toDate(value);
  if (!date) return "";
  const diff = Date.now() - date.getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "now";
  if (mins < 60) return `${mins}m`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h`;
  const days = Math.floor(hrs / 24);
  if (days < 7) return `${days}d`;
  return date.toLocaleDateString("en", { month: "short", day: "numeric" });
}

function formatFull(value: Timestamp | string | null | undefined): string {
  const date = toDate(value);
  if (!date) return "";
  return new Intl.DateTimeFormat("en", {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(date);
}

/** "last seen 3m ago", "last seen 2h ago", "last seen yesterday", etc. */
function formatLastSeen(value: string | null | undefined): string {
  if (!value) return "";
  const date = new Date(value);
  if (isNaN(date.getTime())) return "";
  const diff = Date.now() - date.getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "last seen just now";
  if (mins < 60) return `last seen ${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `last seen ${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  if (days === 1) return "last seen yesterday";
  if (days < 7) return `last seen ${days}d ago`;
  return `last seen ${date.toLocaleDateString("en", { month: "short", day: "numeric" })}`;
}

/** Robust deduplication of message arrays by ID and tempId */
function deduplicateMessages(msgs: Message[]): Message[] {
  const confirmedTempIds = new Set<string>();
  const seenIds = new Set<string>();

  // Collect all confirmed tempIds from database messages
  for (const m of msgs) {
    if (!m.id.startsWith("temp-")) {
      const tId = (m as any).tempId;
      if (tId) confirmedTempIds.add(tId);
    }
  }

  const result: Message[] = [];
  for (const m of msgs) {
    // Skip if it's a temporary placeholder that has been replaced/confirmed
    if (m.id.startsWith("temp-") && confirmedTempIds.has(m.id)) {
      continue;
    }
    // Deduplicate standard IDs
    if (!seenIds.has(m.id)) {
      seenIds.add(m.id);
      result.push(m);
    }
  }
  return result;
}


function sortByRecent(list: Conversation[]): Conversation[] {
  return [...list].sort((a, b) => {
    const aT = toDate(a.lastMessageAt)?.getTime() ?? 0;
    const bT = toDate(b.lastMessageAt)?.getTime() ?? 0;
    return bT - aT;
  });
}

// ΓöÇΓöÇΓöÇ Voice Note Player Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function VoiceNotePlayer({ audioUrl }: { audioUrl: string }) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const audio = new Audio(audioUrl);
    audioRef.current = audio;

    const onLoadedMetadata = () => {
      setDuration(audio.duration || 0);
    };
    const onTimeUpdate = () => {
      setCurrentTime(audio.currentTime);
    };
    const onEnded = () => {
      setIsPlaying(false);
      setCurrentTime(0);
    };

    audio.addEventListener("loadedmetadata", onLoadedMetadata);
    audio.addEventListener("timeupdate", onTimeUpdate);
    audio.addEventListener("ended", onEnded);

    if (audio.readyState >= 1) {
      setDuration(audio.duration);
    }

    return () => {
      audio.pause();
      audio.removeEventListener("loadedmetadata", onLoadedMetadata);
      audio.removeEventListener("timeupdate", onTimeUpdate);
      audio.removeEventListener("ended", onEnded);
    };
  }, [audioUrl]);

  const togglePlay = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
      setIsPlaying(false);
    } else {
      audioRef.current.play().catch(() => { });
      setIsPlaying(true);
    }
  };

  const handleScrub = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setCurrentTime(val);
    if (audioRef.current) {
      audioRef.current.currentTime = val;
    }
  };

  const formatTime = (secs: number) => {
    if (isNaN(secs) || !isFinite(secs)) return "0:00";
    const m = Math.floor(secs / 60);
    const s = Math.floor(secs % 60);
    return `${m}:${s.toString().padStart(2, "0")}`;
  };

  return (
    <div className="flex items-center gap-3 py-1 px-1.5 min-w-[200px] select-none text-inherit">
      <button
        onClick={togglePlay}
        type="button"
        className="flex items-center justify-center w-8 h-8 rounded-full bg-white text-slate-950 hover:scale-105 active:scale-95 transition"
      >
        {isPlaying ? (
          <svg className="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24">
            <path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z" />
          </svg>
        ) : (
          <svg className="w-3.5 h-3.5 fill-current ml-0.5" viewBox="0 0 24 24">
            <path d="M8 5v14l11-7z" />
          </svg>
        )}
      </button>
      <div className="flex-1 flex flex-col gap-0.5">
        <input
          type="range"
          min={0}
          max={duration || 100}
          value={currentTime}
          onChange={handleScrub}
          className="w-full accent-slate-950 bg-white/20 h-1 rounded-lg appearance-none cursor-pointer"
        />
        <div className="flex justify-between text-[8px] opacity-60">
          <span>{formatTime(currentTime)}</span>
          <span>{formatTime(duration)}</span>
        </div>
      </div>
    </div>
  );
}

// ΓöÇΓöÇΓöÇ Call Log Bubble ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function CallLogBubble({ msg, currentUserId }: { msg: Message; currentUserId: string }) {
  const isVideo = msg.callType === "video";
  const isMissed = msg.callStatus === "missed";
  const isDeclined = msg.callStatus === "declined";
  const isCompleted = msg.callStatus === "completed";
  const wasCaller = msg.senderId === currentUserId;

  const icon = isVideo ? "≡ƒÄÑ" : "≡ƒô₧";
  const durationLabel = isCompleted && msg.callDuration && msg.callDuration > 0
    ? `${Math.floor(msg.callDuration / 60)}:${String(msg.callDuration % 60).padStart(2, "0")}`
    : null;

  let label: string;
  let colorClass: string;
  if (isCompleted) {
    label = `${isVideo ? "Video" : "Voice"} call ┬╖ ${durationLabel}`;
    colorClass = "text-emerald-400";
  } else if (isMissed) {
    label = wasCaller ? `No answer` : `Missed ${isVideo ? "video" : "voice"} call`;
    colorClass = "text-rose-400";
  } else {
    label = wasCaller ? `Call declined` : `Declined call`;
    colorClass = "text-brand-500";
  }

  return (
    <div className="flex justify-center my-2 select-none">
      <div className="flex items-center gap-2 px-4 py-2 rounded-2xl border border-white/8 bg-slate-900/60 backdrop-blur-sm text-xs">
        <span className="text-base leading-none">{icon}</span>
        <span className={`font-semibold ${colorClass}`}>{label}</span>
        {msg.createdAt && (
          <>
            <span className="text-brand-700">┬╖</span>
            <span className="text-brand-600 text-[10px]">{formatRelative(msg.createdAt)}</span>
          </>
        )}
      </div>
    </div>
  );
}

