export default function NsgramMessagesPage() {
  const { profile, users, socket, socketConnected } = useNsgramAuth();
  const searchParams = useSearchParams();
  const router = useRouter();

  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selectedConversationId, setSelectedConversationId] = useState<string | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [messageText, setMessageText] = useState("");
  const [onlineStatusMap, setOnlineStatusMap] = useState<Record<string, boolean>>({});
  const [lastSeenMap, setLastSeenMap] = useState<Record<string, string | null>>({});
  const [convoLoading, setConvoLoading] = useState(true);
  const [isTyping, setIsTyping] = useState(false); // is the chat partner typing?
  // Track which conversations have unread messages (optimistic, driven by conversation doc fields)
  const [readConvoIds, setReadConvoIds] = useState<Set<string>>(new Set());
  const [replyingToMessage, setReplyingToMessage] = useState<Message | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const [activeMenuMessageId, setActiveMenuMessageId] = useState<string | null>(null);
  const [firestoreError, setFirestoreError] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement | null>(null);
  const messagesContainerRef = useRef<HTMLDivElement | null>(null);
  const inputRef = useRef<HTMLInputElement | null>(null);
  const typingTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null); // debounce for typing-stop

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const recordingIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const recordStreamRef = useRef<MediaStream | null>(null);
  const isMockRecordingRef = useRef(false);
  // Communicates send-vs-cancel decision to the async onstop handler
  const shouldSendRef = useRef(false);

  // ΓöÇΓöÇ Sync convoId from URL ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  useEffect(() => {
    const id = searchParams.get("convoId");
    if (id) setSelectedConversationId(id);
  }, [searchParams]);

  // NOTE: We intentionally do NOT lock body/html overflow here.
  // Doing so fights Android Chrome's dynamic viewport resize when the keyboard
  // opens, causing the header to scroll off-screen. The layout is instead
  // contained by the parent h-dvh overflow-hidden wrapper in layout.tsx.

  const handleInputFocus = useCallback(() => {
    // Scroll the messages container to the bottom smoothly when keyboard appears
    setTimeout(() => {
      if (messagesContainerRef.current) {
        messagesContainerRef.current.scrollTo({
          top: messagesContainerRef.current.scrollHeight,
          behavior: "smooth"
        });
      }
    }, 200);
  }, []);


  // ΓöÇΓöÇ Firestore: real-time conversation list ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  useEffect(() => {
    if (!db || !profile?.id) {
      setConversations([]);
      setConvoLoading(false);
      return;
    }

    const q = query(
      collection(db, "conversations"),
      where("participants", "array-contains", profile.id)
    );

    const unsub = onSnapshot(q, (snap) => {
      const list = snap.docs.map(
        (d) => ({ id: d.id, ...d.data() } as Conversation)
      );
      setConversations(sortByRecent(list));
      setConvoLoading(false);
    });

    return () => unsub();
  }, [profile?.id]);

  // ΓöÇΓöÇ Firestore: load historical messages and listen to updates in real-time ΓöÇΓöÇ
  useEffect(() => {
    if (!db || !selectedConversationId) {
      setMessages([]);
      return;
    }

    const q = query(
      collection(db, "conversations", selectedConversationId, "messages"),
      orderBy("createdAt", "asc")
    );

    const unsub = onSnapshot(
      q,
      (snap) => {
        setFirestoreError(null);
        const dbMsgs = snap.docs.map((d) => ({ id: d.id, ...d.data() } as Message));
        console.log(`[onSnapshot] Fired for convo ${selectedConversationId}. Docs count: ${dbMsgs.length}. FromCache: ${snap.metadata.fromCache}. HasPendingWrites: ${snap.metadata.hasPendingWrites}`);
        setMessages((prev) => {
          const confirmedTempIds = new Set(
            dbMsgs.map((m) => (m as any).tempId).filter(Boolean)
          );
          const pendingTempMsgs = prev.filter(
            (m) => m.id.startsWith("temp-") && !confirmedTempIds.has(m.id)
          );
          return deduplicateMessages([...dbMsgs, ...pendingTempMsgs]);
        });
      },
      (err) => {
        console.error("[onSnapshot] ERROR listening to messages:", err);
        setFirestoreError(err.message);
      }
    );

    return () => unsub();
  }, [selectedConversationId]);

  // ΓöÇΓöÇ markAsRead: emit socket event + optimistically flip local messages ΓöÇΓöÇΓöÇΓöÇΓöÇ
  const markAsRead = useCallback(
    (conversationId: string) => {
      if (!socket || !profile?.id) return;
      socket.emit("mark-as-read", { conversationId, userId: profile.id });
      // Optimistically mark all incoming messages in this convo as read locally
      setMessages((prev) =>
        prev.map((m) =>
          m.senderId !== profile.id ? { ...m, read: true } : m
        )
      );
      // Clear unread flag for this conversation immediately
      setReadConvoIds((prev) => new Set([...prev, conversationId]));
    },
    [socket, profile?.id]
  );

  // ΓöÇΓöÇ Socket.IO: join/leave room + receive incoming messages ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  // Depends on socketConnected so that reconnects automatically re-emit join-room.
  useEffect(() => {
    if (!socket || !selectedConversationId || !profile?.id || !socketConnected) return;

    console.log(`[join-room] Emitting join-room for convo: ${selectedConversationId}`);
    socket.emit("join-room", {
      conversationId: selectedConversationId,
      userId: profile.id,
    });

    // Mark conversation as read the moment we join it
    markAsRead(selectedConversationId);

    // Incoming message from other users in the room
    const onReceiveMessage = (msg: Message) => {
      console.log("[receive-message] Socket event received:", msg.id, msg.text?.slice(0, 30));
      setMessages((prev) =>
        deduplicateMessages(prev.some((m) => m.id === msg.id) ? prev : [...prev, msg])
      );
      // Auto-mark as read since the chat is open
      markAsRead(selectedConversationId);
    };

    socket.on("receive-message", onReceiveMessage);

    return () => {
      socket.emit("leave-room", { conversationId: selectedConversationId });
      socket.off("receive-message", onReceiveMessage);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [socket, socketConnected, selectedConversationId, profile?.id]);

  // ΓöÇΓöÇ Socket.IO: messages-read ΓÇö recipient read our messages (show "Seen") ΓöÇΓöÇΓöÇ
  useEffect(() => {
    if (!socket) return;

    const onMessagesRead = ({ conversationId }: { conversationId: string }) => {
      // If this event is for the currently open convo, mark all our sent messages as read
      if (conversationId === selectedConversationId) {
        setMessages((prev) =>
          prev.map((m) =>
            m.senderId === profile?.id ? { ...m, read: true } : m
          )
        );
      }
    };

    socket.on("messages-read", onMessagesRead);
    return () => socket.off("messages-read", onMessagesRead);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [socket, selectedConversationId, profile?.id]);

  // ΓöÇΓöÇ Socket.IO: own sent message confirmation (always fires, even if offline) ΓöÇ
  useEffect(() => {
    if (!socket) return;

    // Server emits this back to sender after Firestore save.
    // If a temp message exists (optimistic UI), replace it with the real one.
    // Otherwise just append (handles edge cases like page reload mid-send).
    const onMessageSent = (msg: Message & { tempId?: string }) => {
      console.log("[message-sent] Server confirmed message:", msg.id, "tempId:", msg.tempId);
      setMessages((prev) => {
        // Find the temp placeholder by tempId if provided
        const tempIdx = msg.tempId ? prev.findIndex((m) => m.id === msg.tempId) : -1;
        if (tempIdx !== -1) {
          // Swap the temp placeholder with the real confirmed message
          const updated = [...prev];
          updated[tempIdx] = { ...msg };
          return deduplicateMessages(updated);
        }
        // No temp placeholder (e.g. browser refresh) ΓÇö only append if not already present
        return deduplicateMessages(prev.some((m) => m.id === msg.id) ? prev : [...prev, msg]);
      });
    };

    socket.on("message-sent", onMessageSent);

    return () => {
      socket.off("message-sent", onMessageSent);
    };
  }, [socket]);

  // ΓöÇΓöÇ Socket.IO: message-reacted ΓÇö updates reactions on messages ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  useEffect(() => {
    if (!socket) return;

    const onMessageReacted = (data: { messageId: string; reactions: Record<string, string> }) => {
      setMessages((prev) =>
        prev.map((m) =>
          m.id === data.messageId ? { ...m, reactions: data.reactions } : m
        )
      );
    };

    socket.on("message-reacted", onMessageReacted);
    return () => {
      socket.off("message-reacted", onMessageReacted);
    };
  }, [socket]);

  // ΓöÇΓöÇ Socket.IO: global user online/offline status (now also carries lastSeen) ΓöÇ
  useEffect(() => {
    if (!socket) return;

    const onStatus = (data: { userId: string; status: "online" | "offline"; lastSeen?: string | null }) => {
      setOnlineStatusMap((prev) => ({
        ...prev,
        [data.userId]: data.status === "online",
      }));
      if (data.status === "offline" && data.lastSeen !== undefined) {
        setLastSeenMap((prev) => ({ ...prev, [data.userId]: data.lastSeen ?? null }));
      }
      if (data.status === "online") {
        setLastSeenMap((prev) => ({ ...prev, [data.userId]: null }));
      }
    };

    socket.on("user-status", onStatus);
    return () => socket.off("user-status", onStatus);
  }, [socket]);

  // ΓöÇΓöÇ Socket.IO: query selected chat user's online status ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const selectedConversation = useMemo(
    () => conversations.find((c) => c.id === selectedConversationId) ?? null,
    [conversations, selectedConversationId]
  );

  const selectedChatUser = useMemo(() => {
    if (!profile || !selectedConversation) return null;
    const otherId = selectedConversation.participants.find((p) => p !== profile.id);
    return users.find((u) => u.id === otherId) ?? null;
  }, [profile, selectedConversation, users]);

  // ΓöÇΓöÇ WebRTC Voice Call State & Hook ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const voiceCall = useVoiceCall(
    socket,
    profile,
    selectedChatUser,
    selectedConversationId
  );

  useEffect(() => {
    if (!socket || !selectedChatUser?.id) return;

    const checkStatus = () => {
      socket.emit(
        "check-online-status",
        selectedChatUser.id,
        (isOnline: boolean) => {
          setOnlineStatusMap((prev) => ({
            ...prev,
            [selectedChatUser.id]: isOnline,
          }));

          if (isOnline) {
            // Clear last seen value if user is online
            setLastSeenMap((prev) => ({ ...prev, [selectedChatUser.id]: null }));
          } else if (db) {
            // If offline, fetch lastSeen from Firestore
            import("firebase/firestore").then(({ doc, getDoc }) => {
              getDoc(doc(db!, "users", selectedChatUser.id))
                .then((snap) => {
                  const ls = snap.data()?.lastSeen ?? null;
                  setLastSeenMap((prev) => ({ ...prev, [selectedChatUser.id]: ls }));
                })
                .catch(() => { });
            });
          }
        }
      );
    };

    checkStatus();

    // Re-verify status on socket reconnect
    socket.on("connect", checkStatus);

    return () => {
      socket.off("connect", checkStatus);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [socket, selectedChatUser?.id]);

  // ΓöÇΓöÇ Socket.IO: query status for all inbox conversations on load / reconnect ΓöÇΓöÇΓöÇΓöÇ
  useEffect(() => {
    if (!socket || conversations.length === 0 || !profile?.id) return;

    const checkAllInboxStatus = () => {
      conversations.forEach((convo) => {
        const otherId = convo.participants.find((p) => p !== profile.id);
        if (otherId) {
          socket.emit("check-online-status", otherId, (isOnline: boolean) => {
            setOnlineStatusMap((prev) => ({
              ...prev,
              [otherId]: isOnline,
            }));
            if (isOnline) {
              setLastSeenMap((prev) => ({ ...prev, [otherId]: null }));
            }
          });
        }
      });
    };

    checkAllInboxStatus();

    socket.on("connect", checkAllInboxStatus);

    return () => {
      socket.off("connect", checkAllInboxStatus);
    };
  }, [socket, conversations, profile?.id]);

  // ΓöÇΓöÇ Auto-scroll messages ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  // Always scroll to bottom when conversation first loads (messages array changes from empty).
  // After that, only auto-scroll if user is already near the bottom (not scrolled up to read history).
  const prevMsgCountRef = useRef(0);
  useEffect(() => {
    const container = messagesContainerRef.current;
    if (!container) return;

    const isInitialLoad = prevMsgCountRef.current === 0 && messages.length > 0;
    const isNearBottom =
      container.scrollHeight - container.scrollTop - container.clientHeight < 120;

    if (isInitialLoad || isNearBottom) {
      // Use instant scroll on initial load, smooth on new messages
      messagesEndRef.current?.scrollIntoView({
        behavior: isInitialLoad ? "instant" : "smooth",
      });
    }

    prevMsgCountRef.current = messages.length;
  }, [messages]);

  // ΓöÇΓöÇ Focus input when chat opens (only on desktop/large screens) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  useEffect(() => {
    if (selectedConversationId && typeof window !== "undefined" && window.innerWidth >= 1024) {
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [selectedConversationId]);

  // ΓöÇΓöÇ Typing emit: debounced, fires on every keystroke ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const handleTyping = useCallback(() => {
    if (!socket || !selectedConversationId || !profile?.id) return;
    // Emit typing-start
    socket.emit("typing-start", { conversationId: selectedConversationId, userId: profile.id });
    // Clear previous timer and set a new 2s stop timer
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = setTimeout(() => {
      socket.emit("typing-stop", { conversationId: selectedConversationId, userId: profile.id });
    }, 2000);
  }, [socket, selectedConversationId, profile?.id]);

  // ΓöÇΓöÇ Scroll to Message highlight helper ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const scrollToMessage = useCallback((msgId: string) => {
    const el = document.getElementById(`msg-${msgId}`);
    if (el) {
      el.scrollIntoView({ behavior: "smooth", block: "center" });
      el.classList.add("bg-amber-400/20 border-amber-400/30");
      setTimeout(() => {
        el.classList.remove("bg-amber-400/20 border-amber-400/30");
      }, 1500);
    }
  }, []);

  // ΓöÇΓöÇ Typing indicator: listen for partner's typing events ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  useEffect(() => {
    if (!socket || !selectedConversationId || !selectedChatUser?.id) {
      setIsTyping(false);
      return;
    }

    const onUserTyping = (data: { conversationId: string; userId: string; isTyping: boolean }) => {
      console.log("[user-typing] Received typing status update:", data);
      // Only care about this conversation and the other person (not ourselves)
      if (data.conversationId === selectedConversationId && data.userId === selectedChatUser.id) {
        setIsTyping(data.isTyping);
      }
    };

    socket.on("user-typing", onUserTyping);
    return () => {
      socket.off("user-typing", onUserTyping);
      setIsTyping(false);
    };
  }, [socket, selectedConversationId, selectedChatUser?.id]);

  // Cleanup active typing timeouts on conversation switch or unmount
  useEffect(() => {
    return () => {
      if (typingTimeoutRef.current) {
        clearTimeout(typingTimeoutRef.current);
      }
    };
  }, [selectedConversationId]);

  // ΓöÇΓöÇ Audio Recording Handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const createMockAudioBase64 = (durationSeconds: number): string => {
    const sampleRate = 8000;
    const numSamples = sampleRate * Math.max(1, durationSeconds);
    const buffer = new ArrayBuffer(44 + numSamples * 2);
    const view = new DataView(buffer);

    view.setUint32(0, 0x52494646, false); // "RIFF"
    view.setUint32(4, 36 + numSamples * 2, true);
    view.setUint32(8, 0x57415645, false); // "WAVE"
    view.setUint32(12, 0x666d7420, false); // "fmt "
    view.setUint16(16, 16, true);
    view.setUint16(20, 1, true);
    view.setUint16(22, 1, true);
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * 2, true);
    view.setUint16(32, 2, true);
    view.setUint16(34, 16, true);
    view.setUint32(36, 0x64617461, false); // "data"
    view.setUint32(40, numSamples * 2, true);

    const frequency = 440;
    for (let i = 0; i < numSamples; i++) {
      const t = i / sampleRate;
      const sample = Math.sin(2 * Math.PI * frequency * t) * 0.3 * Math.max(0, 1 - t / Math.max(1, durationSeconds));
      view.setInt16(44 + i * 2, sample * 0x7FFF, true);
    }

    const bytes = new Uint8Array(buffer);
    let binary = "";
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return `data:audio/wav;base64,${window.btoa(binary)}`;
  };

  const startRecording = async () => {
    isMockRecordingRef.current = false;
    shouldSendRef.current = false;
    audioChunksRef.current = [];
    setRecordingDuration(0);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      recordStreamRef.current = stream;

      // Pick the best MIME type, prioritizing mp4 formats for iOS/Apple devices
      const isAppleMobile = /iPad|iPhone|iPod/.test(navigator.userAgent) || 
                            (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);

      const mimeTypesToTry = isAppleMobile
        ? [
            "audio/mp4;codecs=mp4a.40.2",
            "audio/mp4",
            "audio/webm;codecs=opus",
            "audio/webm"
          ]
        : [
            "audio/webm;codecs=opus",
            "audio/webm",
            "audio/ogg;codecs=opus",
            "audio/mp4;codecs=mp4a.40.2",
            "audio/mp4"
          ];

      let mimeType = "";
      for (const type of mimeTypesToTry) {
        if (MediaRecorder.isTypeSupported(type)) {
          mimeType = type;
          break;
        }
      }

      const mediaRecorder = mimeType
        ? new MediaRecorder(stream, { mimeType })
        : new MediaRecorder(stream);

      mediaRecorderRef.current = mediaRecorder;

      mediaRecorder.ondataavailable = (event) => {
        if (event.data && event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };

      // onstop fires AFTER all ondataavailable events complete ΓÇö this is the only
      // correct place to assemble and send the final audio blob.
      mediaRecorder.onstop = () => {
        // Always release the microphone on stop
        if (recordStreamRef.current) {
          recordStreamRef.current.getTracks().forEach((track) => track.stop());
          recordStreamRef.current = null;
        }

        if (!shouldSendRef.current) return; // User cancelled ΓÇö discard

        const chunks = audioChunksRef.current;
        if (chunks.length === 0) return;

        const blobType = mimeType || "audio/webm";
        const audioBlob = new Blob(chunks, { type: blobType });
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);
        reader.onloadend = () => {
          const base64Audio = reader.result as string;
          if (socket && profile && selectedConversation) {
            const tempId = `temp-${Date.now()}`;
            const optimisticVoiceMsg: Message = {
              id: tempId,
              senderId: profile.id,
              text: "≡ƒÄñ Voice note",
              audioUrl: base64Audio,
              createdAt: new Date().toISOString(),
              read: false,
            };
            setMessages((prev) => deduplicateMessages([...prev, optimisticVoiceMsg]));

            socket.emit("send-message", {
              conversationId: selectedConversation.id,
              text: "≡ƒÄñ Voice note",
              audioUrl: base64Audio,
              senderId: profile.id,
              recipientId: selectedChatUser?.id ?? "",
              tempId,
            });
          }
        };
      };

      // Use 250ms timeslice to force mobile Safari and Chrome to emit data chunks regularly,
      // avoiding WebKit bugs that cause silent/empty recordings on stop.
      mediaRecorder.start(250);
      setIsRecording(true);

      recordingIntervalRef.current = setInterval(() => {
        setRecordingDuration((prev) => prev + 1);
      }, 1000);
    } catch (err) {
      console.warn("Microphone access denied or unavailable, using fallback mode:", err);
      isMockRecordingRef.current = true;
      setIsRecording(true);

      recordingIntervalRef.current = setInterval(() => {
        setRecordingDuration((prev) => prev + 1);
      }, 1000);
    }
  };

  const stopRecording = (shouldSend: boolean) => {
    if (recordingIntervalRef.current) {
      clearInterval(recordingIntervalRef.current);
      recordingIntervalRef.current = null;
    }

    setIsRecording(false);

    // Mock / fallback mode (microphone was unavailable)
    if (isMockRecordingRef.current) {
      isMockRecordingRef.current = false;
      // Stop any lingering stream just in case
      if (recordStreamRef.current) {
        recordStreamRef.current.getTracks().forEach((t) => t.stop());
        recordStreamRef.current = null;
      }

      if (shouldSend) {
        const base64Audio = createMockAudioBase64(recordingDuration);
        if (socket && profile && selectedConversation) {
          const tempId = `temp-${Date.now()}`;
          const optimisticVoiceMsg: Message = {
            id: tempId,
            senderId: profile.id,
            text: "≡ƒÄñ Voice note (Generated)",
            audioUrl: base64Audio,
            createdAt: new Date().toISOString(),
            read: false,
          };
          setMessages((prev) => deduplicateMessages([...prev, optimisticVoiceMsg]));

          socket.emit("send-message", {
            conversationId: selectedConversation.id,
            text: "≡ƒÄñ Voice note (Generated)",
            audioUrl: base64Audio,
            senderId: profile.id,
            recipientId: selectedChatUser?.id ?? "",
            tempId,
          });
        }
      }
      return;
    }

    const recorder = mediaRecorderRef.current;
    if (!recorder || recorder.state === "inactive") {
      // Already stopped or never started ΓÇö release stream
      if (recordStreamRef.current) {
        recordStreamRef.current.getTracks().forEach((t) => t.stop());
        recordStreamRef.current = null;
      }
      return;
    }

    // Tell the onstop handler whether to send or discard the audio
    shouldSendRef.current = shouldSend;

    // stop() triggers the final ondataavailable flush, then fires onstop
    recorder.stop();
    mediaRecorderRef.current = null;
  };

  const cancelRecording = () => {
    stopRecording(false);
  };

  // ΓöÇΓöÇ Send message ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const handleSendMessage = useCallback(
    async (e: FormEvent) => {
      e.preventDefault();

      if (!profile || !selectedConversation || !socket) return;

      const text = messageText.trim();
      if (!text) return;

      // Stop typing indicator immediately on send
      if (typingTimeoutRef.current) {
        clearTimeout(typingTimeoutRef.current);
      }

      socket.emit("typing-stop", {
        conversationId: selectedConversation.id,
        userId: profile.id,
      });

      const replyPayload = replyingToMessage
        ? {
          id: replyingToMessage.id,
          text: replyingToMessage.text,
          senderId: replyingToMessage.senderId,
          senderName:
            users.find((u) => u.id === replyingToMessage.senderId)?.displayName ||
            "User",
        }
        : undefined;

      const payload: any = {
        conversationId: selectedConversation.id,
        text,
        senderId: profile.id,
        recipientId: selectedChatUser?.id ?? "",
      };

      if (replyPayload) {
        payload.replyTo = replyPayload;
      }

      // Clear input after sending
      setMessageText("");

      if (replyingToMessage) {
        setReplyingToMessage(null);
      }

      console.log("Emitting send-message to socket:", payload);
      socket.emit("send-message", payload);
    },
    [
      profile,
      selectedConversation,
      socket,
      messageText,
      selectedChatUser,
      replyingToMessage,
      users,
    ]
  );

  const openConvo = useCallback(
    (id: string) => {
      setSelectedConversationId(id);
      router.replace(`/nsgram/messages?convoId=${id}`);
      // Will trigger markAsRead inside the join-room effect when selectedConversationId changes
    },
    [router]
  );

  const closeConvo = useCallback(() => {
    setSelectedConversationId(null);
    router.replace("/nsgram/messages");
  }, [router]);

  const chatUserStatus = selectedChatUser
    ? (onlineStatusMap[selectedChatUser.id] ?? false)
    : false;
  const chatUserLastSeen = selectedChatUser
    ? (lastSeenMap[selectedChatUser.id] ?? null)
    : null;

  if (!profile) return null;

  // Use h-dvh (dynamic viewport height) so the panel resizes when Android
  // Chrome's address bar appears/hides, keeping the header always visible.
  // md:h-[calc(100dvh-0px)] is inherited via parent overflow-hidden wrapper.
  const panelHeight = "h-full w-full min-h-0";

  return (
    <div
