"use client";

import { useEffect, useState } from "react";
import { onAuthStateChanged, User as FirebaseUser } from "firebase/auth";
import { auth } from "@/lib/firebase";
import { API_BASE } from "@/lib/api";
import Link from "next/link";

const getApiBase = () => {
  if (typeof window !== "undefined" && window.location.hostname === "localhost") {
    return "http://localhost:5000";
  }
  return API_BASE || "http://localhost:5000";
};

interface UserStats {
  totalXP: number;
  totalCorrect: number;
  totalAttempts: number;
  currentStreak: number;
  longestStreak: number;
}

interface QuizToday {
  date: string;
  subject: string;
  attemptsCount?: number;
}

export default function DailyQuizCard() {
  const [user, setUser] = useState<FirebaseUser | null>(null);
  const [quiz, setQuiz] = useState<QuizToday | null>(null);
  const [hasAnsweredToday, setHasAnsweredToday] = useState(false);
  const [stats, setStats] = useState<UserStats | null>(null);
  const [loading, setLoading] = useState(true);

  // Monitor auth state
  useEffect(() => {
    if (!auth) return;
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
    });
    return () => unsubscribe();
  }, []);

  // Check if a quiz exists today
  useEffect(() => {
    let retries = 0;
    const checkTodayQuiz = async () => {
      const apiBase = getApiBase();
      try {
        const res = await fetch(`${apiBase}/api/quiz/today`, {
          signal: AbortSignal.timeout(12000),
        });
        if (res.ok) {
          const data = await res.json();
          setQuiz(data.quiz || null);
        }
      } catch {
        // Retry once on timeout/network error
        if (retries === 0) {
          retries++;
          setTimeout(checkTodayQuiz, 3000);
          return;
        }
      } finally {
        setLoading(false);
      }
    };
    checkTodayQuiz();
  }, []);

  // Fetch user stats + today's response status
  useEffect(() => {
    if (!user) {
      // This effect resets derived quiz state when the user signs out.
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setStats(null);
      setHasAnsweredToday(false);
      return;
    }

    const fetchUserData = async () => {
      const apiBase = getApiBase();
      try {
        const idToken = await user.getIdToken();
        const [responseRes, statsRes] = await Promise.all([
          fetch(`${apiBase}/api/quiz/response`, {
            headers: { Authorization: `Bearer ${idToken}` },
            signal: AbortSignal.timeout(6000),
          }),
          fetch(`${apiBase}/api/quiz/stats/${user.uid}`, {
            signal: AbortSignal.timeout(6000),
          }),
        ]);

        if (responseRes.ok) {
          const resData = await responseRes.json();
          setHasAnsweredToday(!!resData.response);
        }
        if (statsRes.ok) {
          const statsData = await statsRes.json();
          setStats(statsData.stats);
        }
      } catch {
        /* silent */
      }
    };

    fetchUserData();
  }, [user]);



  return (
